import * as React from "react"
import { PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";
import ProductDisplay from "../components/productDisplay";
import SubNavigation from "../components/subnav";
import ButtonComponent from "../components/buttons";

const userData: UserProfile = data;

const ProductsPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout 
      data={userData}
      iconAndTextColor="DeepSea"
      footerLogoFill="fill-DeepSea"
      footerColorText="text-DeepSea"
      bgColorPage="Oatmeal"
      bgImage={images.bgProducts.src}
      // footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
    >
        <SubNavigation menuItems={data.submenuProducts} submenuTitle={t("submenu.productsTitle") || ""} />
        <section className={`${styles.section} mt-[300px] sm:mt-[426px]`}>
            <h1 className="head-3 sm:head-1 uppercase" dangerouslySetInnerHTML={{ __html: t("products.title") ?? "" }} />
            <h2 className="head-4 sm:head-2 uppercase mt-8" dangerouslySetInnerHTML={{ __html: t("products.subtitle") ?? "" }} />
        </section>
        <section className={styles.section}>
            <ProductDisplay translationKey="products" submenuItems={data.submenuProducts} />
        </section>
        <section className={`${styles.section} pb-48 pt-12 relative z-40`}>
          <div className="w-full sm:w-1/2">
              <h3 className="head-3 sm:head-1 uppercase" dangerouslySetInnerHTML={{ __html: t("products.footerTitle") ?? "" }} />
              <h4 className="body-2 sm:body-1" dangerouslySetInnerHTML={{ __html: t("products.footerText") ?? "" }} />
              <div className="mt-4 self-start">
                <ButtonComponent isSubmit={false} isDisabled={false} />
              </div>
          </div>
        </section>
    </Layout>
  )
}

export default ProductsPage

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  section: "w-full px-5 sm:px-16 text-DeepSea",
}
import SEO from "../components/seo";
import type { HeadProps } from "gatsby";
import translations from "../locales/en/index.json";
export const Head = ({ location, pageContext }: HeadProps<Record<string, unknown>, { language?: string; i18n?: { originalPath?: string } }>) => (
  <SEO
    data={userData}
    title={translations.seo.products.title}
    description={translations.seo.products.description}
    language={pageContext.language ?? "en"}
    languages={["en"]}
    defaultLanguage="en"
    originalPath={pageContext.i18n?.originalPath ?? location.pathname}
    schemaType="ProfessionalService"
    pageSchemaType="CollectionPage"
    pageSchemaName="Reef Cleaning Products — Eco-Friendly Industrial Solutions"
  />
);
